      ["received wisdom", "общепринятое мнение", "рисИвд уИздэм"], ["cogent", "убедительный, веский", "кОуджэнт"], ["lambast", "разносить в пух и прах", "лэмбЭст"], ["rebuttal", "опровержение", "рибАтл"], ["knee-jerk", "рефлекторный, необдуманный", "ни-джёк"],
      ["moot point", "спорный (или уже неактуальный) вопрос", "мут пойнт"], ["fly in the face of", "противоречить (фактам, здравому смыслу)", "флай ин зэ фэйс ов"], ["take issue with", "оспаривать, не соглашаться с", "тэйк Ишу уиз"], ["hector", "поучать свысока, давить нравоучениями", "хЭктэ"], ["rabble-rousing", "демагогический, будоражащий толпу", "рЭбл-раузинг"]
