      quiz: [
        { q: "Formal letter: We would be grateful if you could ___ the documents by Friday. (предоставить)", a: ["submit", "send us over", "get hold of"], c: 0 }, { q: "Text to a friend: Can't make it tonight, I'm totally ___. (вымотан)", a: ["shattered", "fatigued to a considerable degree", "in a state of exhaustion"], c: 0 },
        { q: "Academic essay: The data ___ that the policy failed. (указывают)", a: ["indicate", "kind of show", "are telling us"], c: 0 }, { q: "Column, deliberate shift: The report runs to 400 pages and, ___, says absolutely nothing. (если коротко)", a: ["in a nutshell", "notwithstanding", "heretofore"], c: 0 },
        { q: "Formal notice: Passengers are ___ to keep their belongings with them. (просят)", a: ["requested", "asked nicely", "told off"], c: 0 }, { q: "Formal: The meeting will ___ at 9 a.m. (начнётся)", a: ["commence", "kick off", "get going"], c: 0 },
        { q: "Informal email: Just a quick note to ___ you know the date's changed.", a: ["let", "inform", "notify"], c: 0 }, { q: "Formal report: Sales ___ significantly in the third quarter. (снизились)", a: ["declined", "took a nosedive", "went down the pan"], c: 0 }
      ]
